import{configured,supabase}from"../services/supabase.js";import{getTenant,resolveTenant}from"../services/tenant.service.js";import{loadIdentity}from"../services/identity.service.js";function fatal(m){document.querySelector("#app").innerHTML=`<div class="screen"><div class="card"><strong>GUVEL</strong><h2>System unavailable</h2><p>${m}</p></div></div>`}function shell(company,identity){const mods=["Dashboard","Capture","Data","Catalog","History","Users","Settings"];document.querySelector("#app").innerHTML=`<div class="shell"><aside class="side"><strong>GUVEL</strong><p class="muted">${company.name}</p><div class="nav">${mods.map(x=>`<button data-m="${x}">${x}</button>`).join("")}</div><hr><button id="logout">Logout</button></aside><main class="main"><p>${identity.display_name||"User"} · ${identity.role}</p><section id="module" class="module"></section></main></div>`;document.querySelectorAll("[data-m]").forEach(b=>b.onclick=()=>document.querySelector("#module").innerHTML=`<h1>${b.dataset.m}</h1><p class="muted">Independent module baseline.</p>`);document.querySelector("[data-m]").click();document.querySelector("#logout").onclick=async()=>{await supabase.auth.signOut();location.reload()}}function login(company){document.querySelector("#app").innerHTML=`<div class="screen"><form class="auth" id="f"><strong>GUVEL</strong><h2>${company.name}</h2><p class="muted">Authorized users only.</p><label>Email</label><input id="e" type="email" required><label>Password</label><input id="p" type="password" required><button class="primary">Sign in</button><div id="err" class="error"></div></form></div>`;document.querySelector("#f").onsubmit=async ev=>{ev.preventDefault();try{const{data,error}=await supabase.auth.signInWithPassword({email:e.value.trim(),password:p.value});if(error)throw error;const identity=await loadIdentity(company.id);shell(company,identity)}catch(x){err.textContent=x.message;console.error(x)}}}async function boot(){if(!configured)return fatal("Configure js/config/env.js with your Supabase URL and anon key.");const slug=getTenant();if(!slug)return fatal("No customer tenant detected in this URL.");try{const company=await resolveTenant(slug);const{data:{session},error}=await supabase.auth.getSession();if(error)throw error;if(!session)return login(company);const identity=await loadIdentity(company.id);shell(company,identity)}catch(x){fatal(x.message);console.error(x)}}boot();
